INSERT INTO learning_units (id, template_code, content_type, title, content_json, sort_order, enabled) VALUES
('unit_phoneme_p_2', 'phoneme', 'PHONEME_DETAIL', '长元音 · /iː/', '{"phonemeId":"p_2","category":"长元音","ipa":"/iː/","description":"较长且紧张的前元音，嘴角略向两侧展开。","audioUrl":null,"mouth":{"type":"smile","color":"#3154ff"},"pronunciationSteps":["舌前部抬高，接近硬腭但不摩擦。","嘴角轻轻向两侧展开。","保持声音长度，不要读成短促的 /ɪ/。"],"exampleWords":[{"wordId":null,"word":"see","ipa":"/siː/","meaning":"看见","audioUrl":null},{"wordId":null,"word":"green","ipa":"/ɡriːn/","meaning":"绿色的","audioUrl":null}],"memoryTip":"看到长音符号 /ː/，要把声音稳稳拉长。","speechFallback":"see"}', 2, TRUE),
('unit_phoneme_p_v_03', 'phoneme', 'PHONEME_DETAIL', '短元音 · /e/', '{"phonemeId":"p_v_03","category":"短元音","ipa":"/e/","description":"短促的前元音，开口比 /ɪ/ 大，比 /æ/ 小。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌前部抬起到中等高度。","嘴唇自然展开，下颌微微打开。","短促发声，不要滑向双元音。"],"exampleWords":[{"wordId":null,"word":"bed","ipa":"/bed/","meaning":"床","audioUrl":null},{"wordId":null,"word":"egg","ipa":"/eɡ/","meaning":"鸡蛋","audioUrl":null}],"memoryTip":"用 bed 的中间音记住 /e/，开口介于 /ɪ/ 和 /æ/ 之间。","speechFallback":"bed"}', 3, TRUE),
('unit_phoneme_p_v_04', 'phoneme', 'PHONEME_DETAIL', '短元音 · /æ/', '{"phonemeId":"p_v_04","category":"短元音","ipa":"/æ/","description":"开口较大的前元音，下颌放低，声音短而清楚。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["舌前部放低，舌尖靠近下齿。","下颌明显打开，嘴唇自然展开。","保持单一短音，不要读成中文的“哎”。"],"exampleWords":[{"wordId":null,"word":"cat","ipa":"/kæt/","meaning":"猫","audioUrl":null},{"wordId":null,"word":"apple","ipa":"/ˈæpl/","meaning":"苹果","audioUrl":null}],"memoryTip":"读 /æ/ 时先把嘴打开，再发短音。","speechFallback":"cat"}', 4, TRUE),
('unit_phoneme_p_v_05', 'phoneme', 'PHONEME_DETAIL', '长元音 · /ɜː/', '{"phonemeId":"p_v_05","category":"长元音","ipa":"/ɜː/","description":"中部偏开的长元音，英式发音中通常不卷舌。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌身保持在口腔中部。","嘴唇放松，开口中等。","平稳拉长声音，不要加明显 r 音。"],"exampleWords":[{"wordId":null,"word":"bird","ipa":"/bɜːd/","meaning":"鸟","audioUrl":null},{"wordId":null,"word":"word","ipa":"/wɜːd/","meaning":"单词","audioUrl":null}],"memoryTip":"看到 bird、word 中的英式长元音，先稳住中间音。","speechFallback":"bird"}', 5, TRUE),
('unit_phoneme_p_v_06', 'phoneme', 'PHONEME_DETAIL', '短元音 · /ə/', '{"phonemeId":"p_v_06","category":"短元音","ipa":"/ə/","description":"弱读音节里最常见的中央元音，轻、短、放松。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌头和嘴唇都保持放松。","声音很轻，不要用力咬字。","常出现在非重读音节中。"],"exampleWords":[{"wordId":null,"word":"about","ipa":"/əˈbaʊt/","meaning":"关于","audioUrl":null},{"wordId":null,"word":"banana","ipa":"/bəˈnɑːnə/","meaning":"香蕉","audioUrl":null}],"memoryTip":"把 /ə/ 当作弱读里的轻声，越放松越自然。","speechFallback":"about"}', 6, TRUE),
('unit_phoneme_p_v_07', 'phoneme', 'PHONEME_DETAIL', '短元音 · /ʌ/', '{"phonemeId":"p_v_07","category":"短元音","ipa":"/ʌ/","description":"短促的中后元音，开口自然，声音干脆。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["舌身放在口腔中部偏后。","下颌自然打开，嘴唇不圆。","短促发声，不要读成 /ɑː/。"],"exampleWords":[{"wordId":null,"word":"cup","ipa":"/kʌp/","meaning":"杯子","audioUrl":null},{"wordId":null,"word":"bus","ipa":"/bʌs/","meaning":"公共汽车","audioUrl":null}],"memoryTip":"用 cup 的中间音记住 /ʌ/：短、开、不圆唇。","speechFallback":"cup"}', 7, TRUE),
('unit_phoneme_p_v_08', 'phoneme', 'PHONEME_DETAIL', '长元音 · /uː/', '{"phonemeId":"p_v_08","category":"长元音","ipa":"/uː/","description":"较长的后高元音，双唇收圆，声音保持稳定。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌后部抬高。","双唇收圆并略向前。","把声音拉长，不要读成短 /ʊ/。"],"exampleWords":[{"wordId":null,"word":"blue","ipa":"/bluː/","meaning":"蓝色的","audioUrl":null},{"wordId":null,"word":"moon","ipa":"/muːn/","meaning":"月亮","audioUrl":null}],"memoryTip":"长音 /uː/ 像 blue 的元音，要圆唇并保持长度。","speechFallback":"blue"}', 8, TRUE),
('unit_phoneme_p_v_09', 'phoneme', 'PHONEME_DETAIL', '短元音 · /ʊ/', '{"phonemeId":"p_v_09","category":"短元音","ipa":"/ʊ/","description":"短促的后元音，圆唇程度比 /uː/ 更轻。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌后部抬起但不要过紧。","嘴唇轻微收圆。","快速发声，避免拉成长音。"],"exampleWords":[{"wordId":null,"word":"book","ipa":"/bʊk/","meaning":"书","audioUrl":null},{"wordId":null,"word":"good","ipa":"/ɡʊd/","meaning":"好的","audioUrl":null}],"memoryTip":"用 book 的短元音区分 /ʊ/ 和 /uː/。","speechFallback":"book"}', 9, TRUE),
('unit_phoneme_p_v_10', 'phoneme', 'PHONEME_DETAIL', '长元音 · /ɔː/', '{"phonemeId":"p_v_10","category":"长元音","ipa":"/ɔː/","description":"较长的后元音，开口较大，双唇略圆。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["舌后部放低。","嘴唇略收圆，下颌打开。","保持长音，不要读成短 /ɒ/。"],"exampleWords":[{"wordId":null,"word":"law","ipa":"/lɔː/","meaning":"法律","audioUrl":null},{"wordId":null,"word":"door","ipa":"/dɔː/","meaning":"门","audioUrl":null}],"memoryTip":"看到 /ː/ 先提醒自己：声音要拉长。","speechFallback":"law"}', 10, TRUE),
('unit_phoneme_p_v_11', 'phoneme', 'PHONEME_DETAIL', '短元音 · /ɒ/', '{"phonemeId":"p_v_11","category":"短元音","ipa":"/ɒ/","description":"英式短后元音，开口大，声音短促。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["舌后部放低。","下颌打开，嘴唇略圆。","快速发出短音，不要拖成长音。"],"exampleWords":[{"wordId":null,"word":"hot","ipa":"/hɒt/","meaning":"热的","audioUrl":null},{"wordId":null,"word":"box","ipa":"/bɒks/","meaning":"盒子","audioUrl":null}],"memoryTip":"用 hot 记住英式 /ɒ/，短而开。","speechFallback":"hot"}', 11, TRUE),
('unit_phoneme_p_v_12', 'phoneme', 'PHONEME_DETAIL', '长元音 · /ɑː/', '{"phonemeId":"p_v_12","category":"长元音","ipa":"/ɑː/","description":"开口较大的后元音，英式读法中常见于 car、park。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["舌身后缩并放低。","下颌打开，嘴唇自然。","保持长音，不要加卷舌。"],"exampleWords":[{"wordId":null,"word":"car","ipa":"/kɑː/","meaning":"汽车","audioUrl":null},{"wordId":null,"word":"park","ipa":"/pɑːk/","meaning":"公园","audioUrl":null}],"memoryTip":"英式 /ɑː/ 常写在 ar 中，长而开。","speechFallback":"car"}', 12, TRUE),
('unit_phoneme_p_v_13', 'phoneme', 'PHONEME_DETAIL', '双元音 · /eɪ/', '{"phonemeId":"p_v_13","category":"双元音","ipa":"/eɪ/","description":"从 /e/ 向 /ɪ/ 滑动的双元音，结尾轻收。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["先发接近 /e/ 的起点。","舌位向 /ɪ/ 方向轻轻滑动。","结尾收短，不要分成两个独立音节。"],"exampleWords":[{"wordId":null,"word":"day","ipa":"/deɪ/","meaning":"一天","audioUrl":null},{"wordId":null,"word":"rain","ipa":"/reɪn/","meaning":"雨","audioUrl":null}],"memoryTip":"双元音要有滑动感，day 不是两个音节。","speechFallback":"day"}', 13, TRUE),
('unit_phoneme_p_v_14', 'phoneme', 'PHONEME_DETAIL', '双元音 · /aɪ/', '{"phonemeId":"p_v_14","category":"双元音","ipa":"/aɪ/","description":"从开口较大的 /a/ 向 /ɪ/ 滑动。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["先打开口腔发起点音。","舌位向前上方滑到 /ɪ/。","一次连贯完成，不要停顿。"],"exampleWords":[{"wordId":null,"word":"my","ipa":"/maɪ/","meaning":"我的","audioUrl":null},{"wordId":null,"word":"time","ipa":"/taɪm/","meaning":"时间","audioUrl":null}],"memoryTip":"读 /aɪ/ 时先开再收，像 my 的元音。","speechFallback":"my"}', 14, TRUE),
('unit_phoneme_p_v_15', 'phoneme', 'PHONEME_DETAIL', '双元音 · /ɔɪ/', '{"phonemeId":"p_v_15","category":"双元音","ipa":"/ɔɪ/","description":"从圆唇的 /ɔ/ 向 /ɪ/ 滑动，常见于 oy、oi。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["先发带圆唇感的起点。","舌位向 /ɪ/ 方向滑动。","保持一个音节内完成。"],"exampleWords":[{"wordId":null,"word":"boy","ipa":"/bɔɪ/","meaning":"男孩","audioUrl":null},{"wordId":null,"word":"toy","ipa":"/tɔɪ/","meaning":"玩具","audioUrl":null}],"memoryTip":"看到 oy、oi 时常读成滑动的 /ɔɪ/。","speechFallback":"boy"}', 15, TRUE),
('unit_phoneme_p_v_16', 'phoneme', 'PHONEME_DETAIL', '双元音 · /əʊ/', '{"phonemeId":"p_v_16","category":"双元音","ipa":"/əʊ/","description":"英式读法中从中央元音向 /ʊ/ 滑动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["起点轻而放松。","嘴唇逐渐收圆。","结尾轻收，不要读成两个音节。"],"exampleWords":[{"wordId":null,"word":"go","ipa":"/ɡəʊ/","meaning":"去","audioUrl":null},{"wordId":null,"word":"home","ipa":"/həʊm/","meaning":"家","audioUrl":null}],"memoryTip":"英式 go 的元音是从放松到收圆的滑动。","speechFallback":"go"}', 16, TRUE),
('unit_phoneme_p_v_17', 'phoneme', 'PHONEME_DETAIL', '双元音 · /aʊ/', '{"phonemeId":"p_v_17","category":"双元音","ipa":"/aʊ/","description":"从开口的 /a/ 向 /ʊ/ 滑动，结尾嘴唇收圆。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["先打开口腔发起点音。","声音滑向 /ʊ/。","结尾嘴唇轻轻收圆。"],"exampleWords":[{"wordId":null,"word":"now","ipa":"/naʊ/","meaning":"现在","audioUrl":null},{"wordId":null,"word":"house","ipa":"/haʊs/","meaning":"房子","audioUrl":null}],"memoryTip":"读 /aʊ/ 时注意最后的收圆动作。","speechFallback":"now"}', 17, TRUE),
('unit_phoneme_p_v_18', 'phoneme', 'PHONEME_DETAIL', '双元音 · /ɪə/', '{"phonemeId":"p_v_18","category":"双元音","ipa":"/ɪə/","description":"从 /ɪ/ 向中央元音 /ə/ 滑动，英式发音中常见。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["先发短而轻的 /ɪ/。","舌位放松滑向 /ə/。","结尾不要加明显卷舌音。"],"exampleWords":[{"wordId":null,"word":"near","ipa":"/nɪə/","meaning":"附近","audioUrl":null},{"wordId":null,"word":"ear","ipa":"/ɪə/","meaning":"耳朵","audioUrl":null}],"memoryTip":"看到 near 的英式读法，听 /ɪ/ 到 /ə/ 的变化。","speechFallback":"near"}', 18, TRUE),
('unit_phoneme_p_v_19', 'phoneme', 'PHONEME_DETAIL', '双元音 · /eə/', '{"phonemeId":"p_v_19","category":"双元音","ipa":"/eə/","description":"从 /e/ 向 /ə/ 滑动，英式发音中结尾放松。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["先发清楚的 /e/ 起点。","舌位放松滑向 /ə/。","保持一个音节，不要加卷舌。"],"exampleWords":[{"wordId":null,"word":"hair","ipa":"/heə/","meaning":"头发","audioUrl":null},{"wordId":null,"word":"care","ipa":"/keə/","meaning":"关心","audioUrl":null}],"memoryTip":"用 hair 记住 /eə/：先 /e/，再放松。","speechFallback":"hair"}', 19, TRUE),
('unit_phoneme_p_v_20', 'phoneme', 'PHONEME_DETAIL', '双元音 · /ʊə/', '{"phonemeId":"p_v_20","category":"双元音","ipa":"/ʊə/","description":"从 /ʊ/ 向 /ə/ 滑动的英式双元音，现代口音中有时会变化。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["先发短而圆的 /ʊ/。","舌位和嘴唇逐渐放松。","结尾落到轻的 /ə/。"],"exampleWords":[{"wordId":null,"word":"tour","ipa":"/tʊə/","meaning":"旅行","audioUrl":null},{"wordId":null,"word":"pure","ipa":"/pjʊə/","meaning":"纯净的","audioUrl":null}],"memoryTip":"这一音在不同口音中变化较多，先按英式 /ʊə/ 建立基础。","speechFallback":"tour"}', 20, TRUE),
('unit_phoneme_p_3', 'phoneme', 'PHONEME_DETAIL', '爆破音 · /p/', '{"phonemeId":"p_3","category":"爆破音","ipa":"/p/","description":"清双唇爆破音，双唇闭合后突然放开，声带不振动。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["双唇完全闭合，先挡住气流。","声带保持不振动。","突然打开双唇，送出短促气流。"],"exampleWords":[{"wordId":null,"word":"pen","ipa":"/pen/","meaning":"钢笔","audioUrl":null},{"wordId":null,"word":"map","ipa":"/mæp/","meaning":"地图","audioUrl":null}],"memoryTip":"摸喉咙不应有振动，重点听爆破气流。","speechFallback":"pen"}', 21, TRUE),
('unit_phoneme_p_c_02', 'phoneme', 'PHONEME_DETAIL', '爆破音 · /b/', '{"phonemeId":"p_c_02","category":"爆破音","ipa":"/b/","description":"浊双唇爆破音，动作像 /p/，但声带振动。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["双唇闭合挡住气流。","声带开始振动。","打开双唇释放声音。"],"exampleWords":[{"wordId":null,"word":"bag","ipa":"/bæɡ/","meaning":"包","audioUrl":null},{"wordId":null,"word":"cab","ipa":"/kæb/","meaning":"出租车","audioUrl":null}],"memoryTip":"用声带振动区分 /b/ 和 /p/。","speechFallback":"bag"}', 22, TRUE),
('unit_phoneme_p_c_03', 'phoneme', 'PHONEME_DETAIL', '爆破音 · /t/', '{"phonemeId":"p_c_03","category":"爆破音","ipa":"/t/","description":"清齿龈爆破音，舌尖抵住齿龈后释放。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖抵住上齿龈。","声带不振动，气流被短暂挡住。","舌尖离开，释放清脆爆破。"],"exampleWords":[{"wordId":null,"word":"tea","ipa":"/tiː/","meaning":"茶","audioUrl":null},{"wordId":null,"word":"late","ipa":"/leɪt/","meaning":"迟的","audioUrl":null}],"memoryTip":"词首 /t/ 常带明显送气，词尾则短促收住。","speechFallback":"tea"}', 23, TRUE),
('unit_phoneme_p_c_04', 'phoneme', 'PHONEME_DETAIL', '爆破音 · /d/', '{"phonemeId":"p_c_04","category":"爆破音","ipa":"/d/","description":"浊齿龈爆破音，舌尖位置像 /t/，但声带振动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖抵住上齿龈。","声带振动。","舌尖放开，让声音爆破出来。"],"exampleWords":[{"wordId":null,"word":"dog","ipa":"/dɒɡ/","meaning":"狗","audioUrl":null},{"wordId":null,"word":"add","ipa":"/æd/","meaning":"添加","audioUrl":null}],"memoryTip":"先摸喉咙，能感到振动就是 /d/ 的关键。","speechFallback":"dog"}', 24, TRUE),
('unit_phoneme_p_c_05', 'phoneme', 'PHONEME_DETAIL', '爆破音 · /k/', '{"phonemeId":"p_c_05","category":"爆破音","ipa":"/k/","description":"清软腭爆破音，舌后部抬起阻住气流后释放。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌后部抬向软腭。","声带不振动，气流短暂受阻。","舌后部放开，送出清爆破。"],"exampleWords":[{"wordId":null,"word":"key","ipa":"/kiː/","meaning":"钥匙","audioUrl":null},{"wordId":null,"word":"back","ipa":"/bæk/","meaning":"后面","audioUrl":null}],"memoryTip":"注意 /k/ 的发力点在口腔后部。","speechFallback":"key"}', 25, TRUE),
('unit_phoneme_p_c_06', 'phoneme', 'PHONEME_DETAIL', '爆破音 · /ɡ/', '{"phonemeId":"p_c_06","category":"爆破音","ipa":"/ɡ/","description":"浊软腭爆破音，位置像 /k/，但声带振动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌后部抬起接近软腭。","声带振动。","放开阻塞，发出浊爆破音。"],"exampleWords":[{"wordId":null,"word":"give","ipa":"/ɡɪv/","meaning":"给","audioUrl":null},{"wordId":null,"word":"garden","ipa":"/ˈɡɑːdn/","meaning":"花园","audioUrl":null}],"memoryTip":"把 /ɡ/ 和 /k/ 放在一起练，差别主要在声带。","speechFallback":"give"}', 26, TRUE),
('unit_phoneme_p_c_07', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /f/', '{"phonemeId":"p_c_07","category":"摩擦音","ipa":"/f/","description":"清唇齿摩擦音，上齿轻触下唇，声带不振动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["上齿轻轻接触下唇。","声带不振动。","让气流从唇齿缝隙摩擦通过。"],"exampleWords":[{"wordId":null,"word":"fan","ipa":"/fæn/","meaning":"风扇","audioUrl":null},{"wordId":null,"word":"leaf","ipa":"/liːf/","meaning":"叶子","audioUrl":null}],"memoryTip":"不要咬住下唇，只要轻触并送气。","speechFallback":"fan"}', 27, TRUE),
('unit_phoneme_p_c_08', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /v/', '{"phonemeId":"p_c_08","category":"摩擦音","ipa":"/v/","description":"浊唇齿摩擦音，口型像 /f/，但声带振动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["上齿轻触下唇。","保持声带振动。","让声音从唇齿缝隙摩擦通过。"],"exampleWords":[{"wordId":null,"word":"van","ipa":"/væn/","meaning":"货车","audioUrl":null},{"wordId":null,"word":"five","ipa":"/faɪv/","meaning":"五","audioUrl":null}],"memoryTip":"用喉咙振动区分 /v/ 和 /f/。","speechFallback":"van"}', 28, TRUE),
('unit_phoneme_p_c_09', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /θ/', '{"phonemeId":"p_c_09","category":"摩擦音","ipa":"/θ/","description":"清齿间摩擦音，舌尖靠近上下齿之间，声带不振动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖轻放在上下齿之间或靠近齿缝。","声带不振动。","让气流从舌齿之间摩擦出去。"],"exampleWords":[{"wordId":null,"word":"think","ipa":"/θɪŋk/","meaning":"思考","audioUrl":null},{"wordId":null,"word":"bath","ipa":"/bɑːθ/","meaning":"洗澡","audioUrl":null}],"memoryTip":"/θ/ 不是 /s/，舌尖要参与到齿间摩擦。","speechFallback":"think"}', 29, TRUE),
('unit_phoneme_p_c_10', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /ð/', '{"phonemeId":"p_c_10","category":"摩擦音","ipa":"/ð/","description":"浊齿间摩擦音，口型像 /θ/，但声带振动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖靠近上下齿之间。","声带保持振动。","让声音从舌齿之间摩擦通过。"],"exampleWords":[{"wordId":null,"word":"this","ipa":"/ðɪs/","meaning":"这个","audioUrl":null},{"wordId":null,"word":"mother","ipa":"/ˈmʌðə/","meaning":"母亲","audioUrl":null}],"memoryTip":"/ð/ 和 /θ/ 的口型相近，先听声带有没有振动。","speechFallback":"this"}', 30, TRUE),
('unit_phoneme_p_c_11', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /s/', '{"phonemeId":"p_c_11","category":"摩擦音","ipa":"/s/","description":"清齿龈摩擦音，舌尖接近齿龈，气流细而清。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖靠近上齿龈但不堵住气流。","声带不振动。","让气流从窄缝中摩擦通过。"],"exampleWords":[{"wordId":null,"word":"sun","ipa":"/sʌn/","meaning":"太阳","audioUrl":null},{"wordId":null,"word":"rice","ipa":"/raɪs/","meaning":"米饭","audioUrl":null}],"memoryTip":"/s/ 是清音，只有气流摩擦，没有声带振动。","speechFallback":"sun"}', 31, TRUE),
('unit_phoneme_p_c_12', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /z/', '{"phonemeId":"p_c_12","category":"摩擦音","ipa":"/z/","description":"浊齿龈摩擦音，位置像 /s/，但声带振动。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖靠近上齿龈。","声带振动。","让声音从窄缝中持续摩擦。"],"exampleWords":[{"wordId":null,"word":"zoo","ipa":"/zuː/","meaning":"动物园","audioUrl":null},{"wordId":null,"word":"busy","ipa":"/ˈbɪzi/","meaning":"忙碌的","audioUrl":null}],"memoryTip":"把 /z/ 拉长时能明显感到喉咙振动。","speechFallback":"zoo"}', 32, TRUE),
('unit_phoneme_p_c_13', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /ʃ/', '{"phonemeId":"p_c_13","category":"摩擦音","ipa":"/ʃ/","description":"清腭龈摩擦音，嘴唇略圆，声音像轻轻的 sh。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌前部抬向硬腭后方。","嘴唇略向前收圆。","声带不振动，让气流摩擦通过。"],"exampleWords":[{"wordId":null,"word":"she","ipa":"/ʃiː/","meaning":"她","audioUrl":null},{"wordId":null,"word":"wash","ipa":"/wɒʃ/","meaning":"洗","audioUrl":null}],"memoryTip":"/ʃ/ 比 /s/ 更靠后，嘴唇也更圆。","speechFallback":"she"}', 33, TRUE),
('unit_phoneme_p_c_14', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /ʒ/', '{"phonemeId":"p_c_14","category":"摩擦音","ipa":"/ʒ/","description":"浊腭龈摩擦音，口型像 /ʃ/，但声带振动。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌前部抬向硬腭后方。","嘴唇略圆。","声带振动，发出持续摩擦声。"],"exampleWords":[{"wordId":null,"word":"vision","ipa":"/ˈvɪʒən/","meaning":"视力","audioUrl":null},{"wordId":null,"word":"measure","ipa":"/ˈmeʒə/","meaning":"测量","audioUrl":null}],"memoryTip":"/ʒ/ 常出现在 vision、measure 这类词中。","speechFallback":"vision"}', 34, TRUE),
('unit_phoneme_p_c_15', 'phoneme', 'PHONEME_DETAIL', '摩擦音 · /h/', '{"phonemeId":"p_c_15","category":"摩擦音","ipa":"/h/","description":"清喉擦音，像轻轻呼气，声带通常不振动。","audioUrl":null,"mouth":{"type":"open","color":"#3154ff"},"pronunciationSteps":["口腔自然打开。","从喉部轻轻送出气流。","不要把声音压得太重。"],"exampleWords":[{"wordId":null,"word":"hat","ipa":"/hæt/","meaning":"帽子","audioUrl":null},{"wordId":null,"word":"hello","ipa":"/həˈləʊ/","meaning":"你好","audioUrl":null}],"memoryTip":"/h/ 的关键是轻呼气，不要加中文式的重音。","speechFallback":"hat"}', 35, TRUE),
('unit_phoneme_p_c_16', 'phoneme', 'PHONEME_DETAIL', '破擦音 · /tʃ/', '{"phonemeId":"p_c_16","category":"破擦音","ipa":"/tʃ/","description":"清破擦音，先像 /t/ 堵住，再像 /ʃ/ 摩擦释放。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌尖先形成短暂阻塞。","声带不振动。","阻塞释放后接上 /ʃ/ 的摩擦感。"],"exampleWords":[{"wordId":null,"word":"chip","ipa":"/tʃɪp/","meaning":"芯片","audioUrl":null},{"wordId":null,"word":"watch","ipa":"/wɒtʃ/","meaning":"手表","audioUrl":null}],"memoryTip":"/tʃ/ 是一个连贯的破擦音，不要拆成两个音节。","speechFallback":"chip"}', 36, TRUE),
('unit_phoneme_p_c_17', 'phoneme', 'PHONEME_DETAIL', '破擦音 · /dʒ/', '{"phonemeId":"p_c_17","category":"破擦音","ipa":"/dʒ/","description":"浊破擦音，先像 /d/ 堵住，再像 /ʒ/ 摩擦释放。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌尖先形成短暂阻塞。","声带振动。","阻塞释放后接上浊摩擦声。"],"exampleWords":[{"wordId":null,"word":"jump","ipa":"/dʒʌmp/","meaning":"跳","audioUrl":null},{"wordId":null,"word":"bridge","ipa":"/brɪdʒ/","meaning":"桥","audioUrl":null}],"memoryTip":"/dʒ/ 和 /tʃ/ 的主要差别是声带振动。","speechFallback":"jump"}', 37, TRUE),
('unit_phoneme_p_c_18', 'phoneme', 'PHONEME_DETAIL', '鼻音 · /m/', '{"phonemeId":"p_c_18","category":"鼻音","ipa":"/m/","description":"双唇鼻音，双唇闭合，气流从鼻腔出来。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["双唇闭合。","声带振动。","让气流从鼻腔通过。"],"exampleWords":[{"wordId":null,"word":"man","ipa":"/mæn/","meaning":"男人","audioUrl":null},{"wordId":null,"word":"summer","ipa":"/ˈsʌmə/","meaning":"夏天","audioUrl":null}],"memoryTip":"捏住鼻子时 /m/ 会明显受阻。","speechFallback":"man"}', 38, TRUE),
('unit_phoneme_p_c_19', 'phoneme', 'PHONEME_DETAIL', '鼻音 · /n/', '{"phonemeId":"p_c_19","category":"鼻音","ipa":"/n/","description":"齿龈鼻音，舌尖抵住齿龈，气流从鼻腔出来。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖抵住上齿龈。","声带振动。","口腔通道关闭，气流走鼻腔。"],"exampleWords":[{"wordId":null,"word":"no","ipa":"/nəʊ/","meaning":"不","audioUrl":null},{"wordId":null,"word":"nine","ipa":"/naɪn/","meaning":"九","audioUrl":null}],"memoryTip":"/n/ 的舌尖位置和 /t/、/d/ 相近，但气流走鼻腔。","speechFallback":"no"}', 39, TRUE),
('unit_phoneme_p_c_20', 'phoneme', 'PHONEME_DETAIL', '鼻音 · /ŋ/', '{"phonemeId":"p_c_20","category":"鼻音","ipa":"/ŋ/","description":"软腭鼻音，舌后部抬起，常见于 ng。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌后部抬向软腭。","声带振动。","让气流从鼻腔通过，不要在词尾额外加 /ɡ/。"],"exampleWords":[{"wordId":null,"word":"sing","ipa":"/sɪŋ/","meaning":"唱歌","audioUrl":null},{"wordId":null,"word":"long","ipa":"/lɒŋ/","meaning":"长的","audioUrl":null}],"memoryTip":"词尾 sing 是 /ŋ/，不要读成 /ŋɡ/。","speechFallback":"sing"}', 40, TRUE),
('unit_phoneme_p_c_21', 'phoneme', 'PHONEME_DETAIL', '舌侧音 · /l/', '{"phonemeId":"p_c_21","category":"舌侧音","ipa":"/l/","description":"舌侧音，舌尖接触齿龈，气流从舌头两侧通过。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖抵住上齿龈。","声带振动。","让气流从舌头两侧流出。"],"exampleWords":[{"wordId":null,"word":"leg","ipa":"/leɡ/","meaning":"腿","audioUrl":null},{"wordId":null,"word":"light","ipa":"/laɪt/","meaning":"光","audioUrl":null}],"memoryTip":"/l/ 不是简单的中文“了”，注意舌尖抵住齿龈。","speechFallback":"leg"}', 41, TRUE),
('unit_phoneme_p_c_22', 'phoneme', 'PHONEME_DETAIL', '近音 · /r/', '{"phonemeId":"p_c_22","category":"近音","ipa":"/r/","description":"英式词首近音，舌尖不碰上腭，声音圆润。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖向后轻轻抬起但不接触上腭。","嘴唇可略微收圆。","声带振动，声音自然滑出。"],"exampleWords":[{"wordId":null,"word":"red","ipa":"/red/","meaning":"红色的","audioUrl":null},{"wordId":null,"word":"road","ipa":"/rəʊd/","meaning":"道路","audioUrl":null}],"memoryTip":"英式 /r/ 在词首清楚出现，但舌尖不要弹动。","speechFallback":"red"}', 42, TRUE),
('unit_phoneme_p_c_23', 'phoneme', 'PHONEME_DETAIL', '近音 · /j/', '{"phonemeId":"p_c_23","category":"近音","ipa":"/j/","description":"硬腭近音，类似 yes 开头的轻滑音。","audioUrl":null,"mouth":{"type":"smile","color":"#3154ff"},"pronunciationSteps":["舌前部抬向硬腭。","口腔保持打开，不形成摩擦。","快速滑向后面的元音。"],"exampleWords":[{"wordId":null,"word":"yes","ipa":"/jes/","meaning":"是","audioUrl":null},{"wordId":null,"word":"young","ipa":"/jʌŋ/","meaning":"年轻的","audioUrl":null}],"memoryTip":"/j/ 是辅音滑音，不是元音 /iː/。","speechFallback":"yes"}', 43, TRUE),
('unit_phoneme_p_c_24', 'phoneme', 'PHONEME_DETAIL', '近音 · /w/', '{"phonemeId":"p_c_24","category":"近音","ipa":"/w/","description":"双唇软腭近音，先圆唇再滑向元音。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["双唇先收圆。","舌后部略抬。","快速放开并滑向后面的元音。"],"exampleWords":[{"wordId":null,"word":"we","ipa":"/wiː/","meaning":"我们","audioUrl":null},{"wordId":null,"word":"water","ipa":"/ˈwɔːtə/","meaning":"水","audioUrl":null}],"memoryTip":"/w/ 要先圆唇，不能直接读成元音。","speechFallback":"we"}', 44, TRUE),
('unit_phoneme_p_c_25', 'phoneme', 'PHONEME_DETAIL', '破擦音 · /tr/', '{"phonemeId":"p_c_25","category":"破擦音","ipa":"/tr/","description":"由 /t/ 接 /r/ 形成的连贯音组，常出现在 tr 拼写中。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌尖先做 /t/ 的阻塞。","释放后迅速滑向 /r/。","保持一个连贯音组，不要插入元音。"],"exampleWords":[{"wordId":null,"word":"tree","ipa":"/triː/","meaning":"树","audioUrl":null},{"wordId":null,"word":"train","ipa":"/treɪn/","meaning":"火车","audioUrl":null}],"memoryTip":"读 tr 时中间不要加出“特-瑞”式的额外元音。","speechFallback":"tree"}', 45, TRUE),
('unit_phoneme_p_c_26', 'phoneme', 'PHONEME_DETAIL', '破擦音 · /dr/', '{"phonemeId":"p_c_26","category":"破擦音","ipa":"/dr/","description":"由 /d/ 接 /r/ 形成的连贯音组，声带振动明显。","audioUrl":null,"mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["舌尖先做 /d/ 的阻塞。","声带保持振动。","释放后迅速滑向 /r/。"],"exampleWords":[{"wordId":null,"word":"dress","ipa":"/dres/","meaning":"连衣裙","audioUrl":null},{"wordId":null,"word":"dream","ipa":"/driːm/","meaning":"梦","audioUrl":null}],"memoryTip":"/dr/ 要连读成一个音组，中间不要多出弱元音。","speechFallback":"dress"}', 46, TRUE),
('unit_phoneme_p_c_27', 'phoneme', 'PHONEME_DETAIL', '破擦音 · /ts/', '{"phonemeId":"p_c_27","category":"破擦音","ipa":"/ts/","description":"由 /t/ 接 /s/ 形成的清破擦音，常见于复数或第三人称词尾。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖先形成 /t/ 的短暂阻塞。","声带不振动。","释放后接上 /s/ 的摩擦声。"],"exampleWords":[{"wordId":null,"word":"cats","ipa":"/kæts/","meaning":"猫（复数）","audioUrl":null},{"wordId":null,"word":"lights","ipa":"/laɪts/","meaning":"灯（复数）","audioUrl":null}],"memoryTip":"/ts/ 结尾要轻快收住，不要额外加 /ə/。","speechFallback":"cats"}', 47, TRUE),
('unit_phoneme_p_c_28', 'phoneme', 'PHONEME_DETAIL', '破擦音 · /dz/', '{"phonemeId":"p_c_28","category":"破擦音","ipa":"/dz/","description":"由 /d/ 接 /z/ 形成的浊破擦音，常见于浊音后的复数词尾。","audioUrl":null,"mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["舌尖先形成 /d/ 的短暂阻塞。","声带保持振动。","释放后接上 /z/ 的摩擦声。"],"exampleWords":[{"wordId":null,"word":"beds","ipa":"/bedz/","meaning":"床（复数）","audioUrl":null},{"wordId":null,"word":"cards","ipa":"/kɑːdz/","meaning":"卡片（复数）","audioUrl":null}],"memoryTip":"/dz/ 有声带振动，结尾也不要加额外元音。","speechFallback":"beds"}', 48, TRUE);
